import crypto from 'node:crypto';import {FrameReader,encodeFrame} from '../../src/desktop/websocket.mjs';
const mode=process.argv[2],id='11111111-1111-4111-8111-111111111111';let buffer=Buffer.alloc(0),ready=false,held;
const send=m=>process.stdout.write(encodeFrame(Buffer.from(JSON.stringify(m))));
const parser=new FrameReader({onMessage:s=>{const m=JSON.parse(s);if(m.method==='initialized')return;if(m.id===777&&m.error){send({id:held,result:{thread:{id,name:'approval rejected',turns:[]}}});return;}if(!m.method)return;
if(m.method==='initialize')send({id:m.id,result:{userAgent:'fixture'}});else if(m.method==='account/read')send({id:m.id,result:{account:{type:'chatgpt'},requiresOpenaiAuth:true}});else if(m.method==='thread/read'){if(mode==='timeout')return;if(mode==='approval'){held=m.id;send({id:777,method:'item/commandExecution/requestApproval',params:{}});return;}send({id:m.id,result:{thread:{id:m.params.threadId,name:'Example chat',turns:[]}}});}else if(m.method==='thread/queue/list'){mode==='unsupported'?send({id:m.id,error:{code:-32601,message:'not available'}}):send({id:m.id,result:{data:[],nextCursor:null}});}else if(m.method==='thread/queue/add')send({id:m.id,result:{queuedSubmission:{id:'queued'}}});else if(m.method==='thread/list')send({id:m.id,result:{data:[],nextCursor:null}});else send({id:m.id,error:{code:-32601,message:'unexpected'}});}});
process.stdin.on('data',part=>{buffer=Buffer.concat([buffer,part]);if(!ready){const end=buffer.indexOf('\r\n\r\n');if(end<0)return;const key=buffer.toString().match(/Sec-WebSocket-Key: ([^\r]+)/)?.[1];const accept=crypto.createHash('sha1').update(key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').digest('base64');process.stdout.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: '+accept+'\r\n\r\n');buffer=buffer.subarray(end+4);ready=true;}if(buffer.length){parser.push(buffer);buffer=Buffer.alloc(0);}});
process.stdin.on('end',()=>process.exit(0));
